class APIKeyBase(SecurityBase):
    def __init__(self, not_authenticated_status_code: int = HTTP_403_FORBIDDEN):
        self.not_authenticated_status_code = not_authenticated_status_code

    @staticmethod
    def check_api_key(api_key: Optional[str], auto_error: bool, not_authenticated_status_code: int) -> Optional[str]:
        if not api_key:
            if auto_error:
                raise HTTPException(
                    status_code=not_authenticated_status_code, detail="Not authenticated"
                )
            return None
        return api_key

